package ui;

import model.Category;import model.Notice;import model.User;import service.CategoryService;import service.DepartmentService;import service.NoticeService;import service.UserService;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.List;

public class StudentNoticeFrame extends JFrame {
    private final NoticeService noticeService=new NoticeService();private final CategoryService categoryService=new CategoryService();private final UserService userService=new UserService();private final DepartmentService departmentService=new DepartmentService();private final User currentUser;private JTable noticeTable;private DefaultTableModel tableModel;private JTextField searchField;private JComboBox<String> priorityFilter;private JComboBox<Category> categoryFilter;private final dao.NoticeViewDAO noticeViewDAO=new dao.NoticeViewDAO();
    public StudentNoticeFrame(User user){currentUser=user;UITheme.styleFrame(this,"College Notices",1200,680);setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);createUI();loadNotices();setVisible(true);}
    private void createUI(){setLayout(new BorderLayout());JPanel header=new JPanel(new BorderLayout());header.setBackground(Color.WHITE);header.setBorder(BorderFactory.createEmptyBorder(20,26,18,26));JPanel h=new JPanel();h.setOpaque(false);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.add(UITheme.title("College Notices",24));h.add(Box.createVerticalStrut(4));h.add(UITheme.muted("Published announcements available for your department."));header.add(h,BorderLayout.WEST);JButton view=UITheme.button("View Selected",true);view.addActionListener(e->viewSelectedNotice());header.add(view,BorderLayout.EAST);add(header,BorderLayout.NORTH);
        JPanel root=new JPanel(new BorderLayout(0,14));root.setBackground(UITheme.BG);root.setBorder(BorderFactory.createEmptyBorder(16,26,22,26));JPanel filters=UITheme.card();filters.setLayout(new FlowLayout(FlowLayout.LEFT,10,0));searchField=new JTextField(25);UITheme.styleField(searchField);searchField.setPreferredSize(new Dimension(260,40));JButton search=UITheme.button("Search",true);priorityFilter=new JComboBox<>(new String[]{"ALL","LOW","MEDIUM","HIGH"});UITheme.styleCombo(priorityFilter);priorityFilter.setPreferredSize(new Dimension(120,40));categoryFilter=new JComboBox<>();UITheme.styleCombo(categoryFilter);categoryFilter.setPreferredSize(new Dimension(160,40));Category all=new Category();all.setCategoryId(0);all.setCategoryName("ALL");categoryFilter.addItem(all);for(Category c:categoryService.getAllCategories())categoryFilter.addItem(c);filters.add(UITheme.muted("Search"));filters.add(searchField);filters.add(search);filters.add(UITheme.muted("Priority"));filters.add(priorityFilter);filters.add(UITheme.muted("Category"));filters.add(categoryFilter);root.add(filters,BorderLayout.NORTH);
        String[] cols={"ID","Title","Category","Created By","Department","Priority","Status"};tableModel=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};noticeTable=new JTable(tableModel);UITheme.styleTable(noticeTable);UITheme.styleBadgeRenderer(noticeTable,5);UITheme.styleBadgeRenderer(noticeTable,6);noticeTable.getColumnModel().getColumn(0).setPreferredWidth(50);noticeTable.getColumnModel().getColumn(1).setPreferredWidth(300);root.add(new JScrollPane(noticeTable),BorderLayout.CENTER);add(root,BorderLayout.CENTER);
        search.addActionListener(e->searchNotices());searchField.addActionListener(e->searchNotices());priorityFilter.addActionListener(e->searchNotices());categoryFilter.addActionListener(e->searchNotices());noticeTable.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(e.getClickCount()==2)viewSelectedNotice();}});
    }
    private void loadNotices(){tableModel.setRowCount(0);for(Notice n:noticeService.getPublishedNotices(currentUser.getDepartmentId()))addRow(n);}
    private void searchNotices(){String key=searchField.getText().trim();String p=(String)priorityFilter.getSelectedItem();Category c=(Category)categoryFilter.getSelectedItem();int id=c==null?0:c.getCategoryId();tableModel.setRowCount(0);List<Notice> list=noticeService.searchNotices(key,"PUBLISHED",p,id);for(Notice n:list)if(n.getDepartmentId()==null||n.getDepartmentId()==currentUser.getDepartmentId())addRow(n);}
    private void addRow(Notice n){tableModel.addRow(new Object[]{n.getNoticeId(),n.getTitle(),categoryService.getCategoryNameById(n.getCategoryId()),userService.getUserNameById(n.getCreatedBy()),n.getDepartmentId()==null?"All Departments":departmentService.getDepartmentNameById(n.getDepartmentId()),n.getPriority(),n.getStatus()});}
    private void viewSelectedNotice(){int row=noticeTable.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Please select a notice first.","No Selection",JOptionPane.WARNING_MESSAGE);return;}int mr=noticeTable.convertRowIndexToModel(row);int id=(Integer)tableModel.getValueAt(mr,0);for(Notice n:noticeService.getAllNotices())if(n.getNoticeId()==id){noticeViewDAO.recordView(n.getNoticeId(),currentUser.getUserId());new NoticeDetailsFrame(n,categoryService,userService,departmentService);return;}}
}
